"""Orchestrate boundary, multi-seed, continuous and production-gate tasks."""

from __future__ import annotations

import argparse
import copy
import csv
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "code"))

from calibration_platform.formal_tasks import build_formal_calibration_command  # noqa: E402
from calibration_platform.production_validation import (  # noqa: E402
    evaluate_multi_seed_stability,
    evaluate_production_gate,
    evaluate_wlm_boundary_experiment,
)
from scripts.preflight_production_calibration import run as run_preflight  # noqa: E402


EVALUATION_PATTERN = re.compile(r"\bevaluation=(\d+)\b")
CONTINUOUS_PATTERN = re.compile(r"\bprogress=([0-9.]+)\b")


def _write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2, default=str) + "\n",
        encoding="utf-8",
    )


def _label_number(value: float) -> str:
    return f"{value:g}".replace(".", "p")


def _run_command(
    command: list[str],
    stage: str,
    base_progress: float,
    progress_span: float,
    evaluation_total: int | None = None,
    continuous: bool = False,
) -> None:
    print(f"workflow_stage={stage}", flush=True)
    process = subprocess.Popen(
        command,
        cwd=str(ROOT),
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        encoding="utf-8",
        errors="replace",
        bufsize=1,
        shell=False,
        env={**os.environ, "PYTHONIOENCODING": "utf-8"},
    )
    assert process.stdout is not None
    try:
        for line in process.stdout:
            message = f"[{stage}] {line.rstrip()}"
            encoding = sys.stdout.encoding or "utf-8"
            print(
                message.encode(encoding, errors="replace").decode(encoding),
                flush=True,
            )
            fraction = None
            if evaluation_total:
                match = EVALUATION_PATTERN.search(line)
                if match:
                    fraction = min(int(match.group(1)) / max(evaluation_total, 1), 1.0)
            elif continuous:
                match = CONTINUOUS_PATTERN.search(line)
                if match:
                    fraction = min(float(match.group(1)) / 100.0, 1.0)
            if fraction is not None:
                progress = base_progress + progress_span * fraction
                print(f"workflow_progress={progress:.2f} stage={stage}", flush=True)
    finally:
        process.stdout.close()
    return_code = process.wait()
    if return_code != 0:
        raise RuntimeError(f"workflow child stage {stage} exited with code {return_code}")
    print(
        f"workflow_progress={base_progress + progress_span:.2f} stage={stage}",
        flush=True,
    )


def _parameter_space_with_wlm(
    base_path: Path,
    upper_bound: float,
    output_path: Path,
) -> Path:
    payload = json.loads(base_path.read_text(encoding="utf-8-sig"))
    found = False
    for spec in payload.get("parameters", []):
        if spec.get("name") == "runoff.WLM":
            minimum = float(spec["minimum"])
            if upper_bound <= minimum:
                raise ValueError("WLM upper bound must exceed its configured minimum")
            spec["maximum"] = float(upper_bound)
            spec["basis"] = "generated by CAL-WLM-BOUNDARY-07"
            found = True
            break
    if not found:
        raise ValueError("base parameter space does not contain runoff.WLM")
    payload["status"] = "GENERATED_WLM_BOUNDARY_EXPERIMENT"
    _write_json(output_path, payload)
    return output_path


def _formal_report(directory: Path) -> dict[str, Any]:
    return json.loads(
        (directory / "formal_multi_event_report.json").read_text(encoding="utf-8-sig")
    )


def _run_or_resume_formal(
    command: list[str],
    run_dir: Path,
    stage: str,
    base_progress: float,
    progress_span: float,
    evaluation_total: int,
) -> None:
    """[CAL-RESUME-10R] Reuse only a complete formal-run report."""
    report = run_dir / "formal_multi_event_report.json"
    if report.is_file():
        _formal_report(run_dir)
        print(
            f"workflow_progress={base_progress + progress_span:.2f} "
            f"stage={stage}_RESUMED",
            flush=True,
        )
        return
    _run_command(command, stage, base_progress, progress_span, evaluation_total)


def _write_boundary_csv(path: Path, rows: list[dict[str, Any]]) -> None:
    if not rows:
        return
    with path.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def run(request: dict[str, Any], output: Path) -> dict[str, Any]:
    output.mkdir(parents=True, exist_ok=True)
    # [CAL-PREFLIGHT-10P] Fail before a long search if forcing or contracts are invalid.
    preflight_report = run_preflight(request, output / "preflight_report.json")
    if not preflight_report["ready_to_run"]:
        raise RuntimeError(
            f"production preflight failed: {preflight_report['failed_check_ids']}"
        )
    print("workflow_progress=2.00 stage=CAL-PREFLIGHT-10P", flush=True)
    generated = output / "generated_configs"
    generated.mkdir(exist_ok=True)
    formal_root = output / "formal_runs"
    formal_root.mkdir(exist_ok=True)
    wlm_bounds = [float(value) for value in request["wlm_upper_bounds_mm"]]
    search_seeds = [int(value) for value in request["search_seeds"]]
    primary_seed = search_seeds[0]
    total_formal_runs = len(wlm_bounds) + len(search_seeds) - 1
    formal_span = 78.0 / total_formal_runs
    formal_index = 0

    # [CAL-WLM-BOUNDARY-07A] Same split and primary optimizer seed, only WLM upper bound changes.
    boundary_runs: dict[str, Path] = {}
    parameter_spaces: dict[float, Path] = {}
    for upper_bound in wlm_bounds:
        bound_label = _label_number(upper_bound)
        label = f"WLM_{bound_label}"
        parameter_space = _parameter_space_with_wlm(
            Path(request["parameter_space"]),
            upper_bound,
            generated / f"parameter_space_WLM_{bound_label}.json",
        )
        parameter_spaces[upper_bound] = parameter_space
        run_dir = formal_root / f"boundary_{label}_seed_{primary_seed}"
        formal_request = {
            **request,
            "parameter_space": str(parameter_space),
            "search_seed": primary_seed,
        }
        _run_or_resume_formal(
            build_formal_calibration_command(ROOT, formal_request, run_dir),
            run_dir,
            f"BOUNDARY_{label}",
            2.0 + formal_index * formal_span,
            formal_span,
            request["max_evaluations"],
        )
        formal_index += 1
        boundary_runs[label] = run_dir
    boundary_report = evaluate_wlm_boundary_experiment(boundary_runs)
    _write_json(output / "wlm_boundary_report.json", boundary_report)
    _write_boundary_csv(output / "wlm_boundary_metrics.csv", boundary_report["runs"])
    selected_upper = float(boundary_report["selected_upper_bound"])
    selected_label = boundary_report["selected_run"]

    # [CAL-MULTI-SEED-08A] Fixed selected bounds and split; optimizer seed is the only change.
    seed_runs: dict[str, Path] = {
        f"SEED_{primary_seed}": boundary_runs[selected_label]
    }
    for seed in search_seeds[1:]:
        run_dir = formal_root / f"stability_WLM_{_label_number(selected_upper)}_seed_{seed}"
        formal_request = {
            **request,
            "parameter_space": str(parameter_spaces[selected_upper]),
            "search_seed": seed,
        }
        _run_or_resume_formal(
            build_formal_calibration_command(ROOT, formal_request, run_dir),
            run_dir,
            f"MULTI_SEED_{seed}",
            2.0 + formal_index * formal_span,
            formal_span,
            request["max_evaluations"],
        )
        formal_index += 1
        seed_runs[f"SEED_{seed}"] = run_dir
    stability_report = evaluate_multi_seed_stability(
        seed_runs,
        request["stability_criteria"],
    )
    _write_json(output / "multi_seed_stability_report.json", stability_report)
    _write_boundary_csv(output / "multi_seed_run_metrics.csv", stability_report["runs"])
    _write_boundary_csv(output / "multi_seed_parameter_metrics.csv", stability_report["parameters"])

    representative_label = stability_report["representative_run"]
    representative_dir = seed_runs[representative_label]
    representative_parameter_set = representative_dir / "resolved_runoff_parameter_set.json"
    event_report = _formal_report(representative_dir)

    # [CAL-CONTINUOUS-BALANCE-09B] Frozen representative parameters, uninterrupted years.
    continuous_dir = output / "continuous_water_balance"
    nested_script = ROOT / "scripts" / "run_continuous_water_balance.py"
    continuous_command = ([sys.executable, "--xaj-script", str(nested_script)] if getattr(sys, "frozen", False)
                          else [sys.executable, "-u", str(nested_script)]) + [
        "--config",
        request["continuous_balance_config"],
        "--data-root",
        request["data_root"],
        "--precip-dir",
        request["precipitation_directory"],
        "--parameter-set",
        str(representative_parameter_set),
        "--initial-land-state",
        request["initial_land_state"],
        "--output-dir",
        str(continuous_dir),
    ]
    continuous_report_path = continuous_dir / "continuous_water_balance_report.json"
    if continuous_report_path.is_file():
        json.loads(continuous_report_path.read_text(encoding="utf-8-sig"))
        print(
            "workflow_progress=97.00 stage=CONTINUOUS_WATER_BALANCE_RESUMED",
            flush=True,
        )
    else:
        _run_command(
            continuous_command,
            "CONTINUOUS_WATER_BALANCE",
            82.0,
            15.0,
            continuous=True,
        )
    continuous_report = json.loads(
        (continuous_dir / "continuous_water_balance_report.json").read_text(
            encoding="utf-8-sig"
        )
    )
    shutil.copy2(
        continuous_dir / "continuous_water_balance_report.json",
        output / "continuous_water_balance_report.json",
    )

    # [CAL-PRODUCTION-GATE-10A] Explicit thresholds decide the label; no silent promotion.
    gate = evaluate_production_gate(
        boundary_report,
        stability_report,
        continuous_report,
        event_report,
        request["production_criteria"],
    )
    _write_json(output / "production_acceptance_report.json", gate)
    source_parameter_payload = json.loads(
        representative_parameter_set.read_text(encoding="utf-8-sig")
    )
    source_parameter_payload["status"] = gate["status"]
    source_parameter_payload["workflow_id"] = request["workflow_id"]
    source_parameter_payload["representative_seed_run"] = representative_label
    parameter_filename = (
        "production_parameter_set.json"
        if gate["production_approved"]
        else "review_candidate_parameter_set.json"
    )
    _write_json(output / parameter_filename, source_parameter_payload)

    report = {
        "module_id": "PRODUCTION-CALIBRATION-10",
        "workflow_id": request["workflow_id"],
        "status": gate["status"],
        "production_approved": gate["production_approved"],
        "preflight": preflight_report,
        "boundary": boundary_report,
        "multi_seed_stability": stability_report,
        "continuous_water_balance": continuous_report,
        "production_gate": gate,
        "representative_run": representative_label,
        "parameter_file": parameter_filename,
        "formal_run_count": total_formal_runs,
        "output_files": {
            "boundary_report": "wlm_boundary_report.json",
            "preflight_report": "preflight_report.json",
            "stability_report": "multi_seed_stability_report.json",
            "continuous_report": "continuous_water_balance_report.json",
            "acceptance_report": "production_acceptance_report.json",
            "parameter_set": parameter_filename,
        },
    }
    _write_json(output / "production_workflow_report.json", report)
    with tempfile.TemporaryDirectory(prefix="production_workflow_archive_") as temporary:
        archive = shutil.make_archive(
            str(Path(temporary) / "production_workflow_artifacts"),
            "zip",
            root_dir=output,
        )
        shutil.copy2(archive, output / "production_workflow_artifacts.zip")
    print(f"workflow_progress=100.00 stage={gate['status']}", flush=True)
    print(json.dumps(report, ensure_ascii=False, indent=2), flush=True)
    return report


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--request", required=True)
    parser.add_argument("--output-dir", required=True)
    args = parser.parse_args()
    request = json.loads(Path(args.request).read_text(encoding="utf-8-sig"))
    run(request, Path(args.output_dir).resolve())
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
